{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, c.service_name, c.span_name, count(*) n, round(avg(c.duration/1e6),1) client_ms, round(avg(s.duration/1e6),3) server_ms, round(avg(epoch(s.time)-epoch(c.time))*1000,1) start_lag_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.span_name='geo.Geo/Nearby' AND c.service_name='search' GROUP BY 1,2,3 UNION ALL SELECT 'norm', c.service_name, c.span_name, count(*), round(avg(c.duration/1e6),1), round(avg(s.duration/1e6),3), round(avg(epoch(s.time)-epoch(c.time))*1000,1) FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.span_name='geo.Geo/Nearby' AND c.service_name='search' GROUP BY 1,2,3",
          "claim": "search→geo client calls take about 1.7 s to start the geo server span, while geo server processing stays about 0.15 ms, versus 0.3 ms lag normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, span_name, service_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='geo' AND attr_span_kind='Server' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', span_name, service_name, attr_span_kind, count(*), round(quantile_cont(duration,0.95)/1e6,2) FROM normal_traces WHERE service_name='geo' AND attr_span_kind='Server' GROUP BY 1,2,3,4",
          "claim": "Geo's own server-side Nearby spans stay fast (p95 well under 1 ms) in both periods, so the delay is not inside geo."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, c.service_name, c.span_name, count(*) n, round(avg(c.duration/1e6),1) client_ms, round(avg(s.duration/1e6),3) server_ms, round(avg(epoch(s.time)-epoch(c.time))*1000,1) start_lag_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.span_name='geo.Geo/Nearby' AND c.service_name='search' GROUP BY 1,2,3",
          "claim": "Search's geo.Geo/Nearby client span averages about 1699 ms, nearly all of it spent before geo starts handling the request."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, c.service_name, c.span_name, count(*) n, round(avg(c.duration/1e6),1) client_ms, round(avg(s.duration/1e6),1) server_ms, round(avg(epoch(s.time)-epoch(c.time))*1000,1) start_lag_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.span_name='search.Search/Nearby' AND c.service_name='frontend' GROUP BY 1,2,3",
          "claim": "Frontend's search.Search/Nearby client span averages about 1675 ms, matching search's server span duration, so search's slowness propagates to frontend."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), round(quantile_cont(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1,2",
          "claim": "User-facing frontend HTTP /hotels p95 rises from about 13 ms normally to about 2.5 s during the incident."
        }
      ]
    }
  ]
}
